import React, { useEffect, useState } from "react";
import { getResults } from "../api";

export default function ResultsPage({ token, handleLogout }) {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // Polling every 5 seconds
  useEffect(() => {
    const fetchResults = async () => {
      try {
        const res = await getResults(token);
        setResults(res.data);
      } catch {
        setError("Failed to fetch results");
      } finally {
        setLoading(false);
      }
    };

    fetchResults();
    const interval = setInterval(fetchResults, 5000);
    return () => clearInterval(interval);
  }, [token]);

  if (loading) return <p className="text-center mt-10">Loading results...</p>;
  if (error) return <p className="text-red-600 text-center mt-10">{error}</p>;

  return (
    <div className="max-w-4xl mx-auto mt-10 p-4">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-primary">Election Results</h2>
        <button
          onClick={handleLogout}
          className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary"
        >
          Logout
        </button>
      </div>

      <table className="w-full table-auto border-collapse border border-gray-300 text-center">
        <thead>
          <tr className="bg-primary text-white">
            <th className="border border-gray-300 px-4 py-2">Candidate</th>
            <th className="border border-gray-300 px-4 py-2">Party</th>
            <th className="border border-gray-300 px-4 py-2">Votes</th>
          </tr>
        </thead>
        <tbody>
          {results.map((r) => (
            <tr key={r._id} className="hover:bg-blue-50">
              <td className="border border-gray-300 px-4 py-2">{r.name}</td>
              <td className="border border-gray-300 px-4 py-2">{r.party}</td>
              <td className="border border-gray-300 px-4 py-2">{r.voteCount}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
